story.text:
#world-clear-view{position:fixed;inset:0;z-index:65;pointer-events:none;display:flex;justify-content:flex-end;align-items:center;padding:92px 30px 64px;color:#eaf0f5;font:15px/1.65 system-ui,sans-serif}
      #world-clear-view *{box-sizing:border-box}#world-clear-view [hidden]{display:none!important}
      #world-clear-view .rain-story{pointer-events:auto;width:min(420px,42vw);max-height:100%;overflow:auto;background:rgba(17,28,39,.94);border:1px solid #4b6273;border-radius:10px;padding:25px;box-shadow:0 18px 50px #0005}
      #world-clear-view .rain-eyebrow{font-size:12px;letter-spacing:.15em;color:#a1b5c4}#world-clear-view h1{font-size:23px;font-weight:500;margin:9px 0 17px}
      #world-clear-view p{margin:0 0 17px}#world-clear-view .rain-choices{display:grid;gap:10px}#world-clear-view button{cursor:pointer;font:inherit;border:1px solid #547285;border-radius:5px;color:#eaf0f5;background:#233c4d;padding:11px 14px;text-align:left;width:100%}
      #world-clear-view button:hover{background:#345468}#world-clear-view button:focus-visible{outline:2px solid #ceeaf1;outline-offset:3px}#world-clear-view button:disabled{cursor:default;opacity:.5}#world-clear-view button[data-selected=true]{opacity:1;border-color:#a8d4d9;background:#31555b}
      #world-clear-view .rain-result{border-top:1px solid #4b6273;margin-top:18px;padding-top:16px;color:#b7d3db}#world-clear-view .rain-account{border-top:1px solid #4b6273;margin-top:17px;padding-top:13px;font-size:13px;color:#a9bcc9;display:grid;gap:3px}
      #world-clear-view .rain-entry{margin-top:12px;background:#506c6d;border-color:#a3ced0}#world-clear-view .rain-error{font-size:13px;color:#ffd0a0;margin:12px 0 0}#world-clear-view .rain-caption{font-size:12px;color:#98aebd;margin:9px 0 0}
      @media(max-width:800px){#world-clear-view{padding:72px 16px 35px}#world-clear-view .rain-story{width:min(390px,60vw);padding:19px}#world-clear-view h1{font-size:20px}#world-clear-view{font-size:14px}}
      @media(max-height:600px){#world-clear-view{padding:70px 16px 30px}#world-clear-view .rain-story{padding:17px}#world-clear-view h1{font-size:20px;margin-bottom:10px}#world-clear-view p{margin-bottom:11px}#world-clear-view button{padding:8px 11px}#world-clear-view .rain-choices{gap:7px}}


        PRIMARY · 旧站台
        雨中遗失的名字雨停前，你在旧站台遇见一位同伴。她攥着一张被雨浸湿的车票：“我记得要等一个人，却忘了他的名字。你愿意陪我想一想吗？”
        把伞移向她，陪她听一会儿雨和她读车票背面的字，找回约定答应陪她等到雨停，再一起出发
        同行的记忆留在雨声里。聆听 · 雨后回响完整聆听并演奏这首世界之曲；离开后仍可回来。
        世界通关：未完成首次世界通关：未完成复制权限：未取得
        重试保存

worldChart.text:
#world-chart-view{position:fixed;inset:0;z-index:75;color:#e7f0f5;font:15px/1.5 system-ui,sans-serif;background:radial-gradient(ellipse at 52% 42%,#284d5b,#142730 60%,#111c24);display:grid;grid-template-rows:auto 1fr auto}
      #world-chart-view *{box-sizing:border-box}#world-chart-view [hidden]{display:none!important}
      #world-chart-view header{display:flex;align-items:center;gap:20px;padding:22px 28px;border-bottom:1px solid #5c819055}#world-chart-view h1{font-size:23px;font-weight:500;margin:0}#world-chart-view .rain-title{margin-right:auto}#world-chart-view .rain-subtitle{font-size:12px;color:#a0bfcb;margin-top:5px}
      #world-chart-view button{cursor:pointer;font:inherit;color:#dfedf4;background:#28424f;border:1px solid #5b7c8b;border-radius:5px;padding:8px 14px}#world-chart-view button:hover{background:#3c606f}#world-chart-view button:focus-visible{outline:2px solid #ceeaf1;outline-offset:3px}
      #world-chart-view .rain-chart-stage{min-height:0;position:relative;padding:20px 28px}#world-chart-view canvas{display:block;width:100%;height:100%;border:1px solid #496b7c66;border-radius:7px;background:#10212a66}#world-chart-view .rain-playing-caption{position:absolute;left:42px;top:29px;font-size:13px;color:#bfd3dd}
      #world-chart-view footer{border-top:1px solid #5c819055;padding:17px 28px 22px;background:#152a3388}#world-chart-view .rain-progress-row{display:flex;gap:18px;align-items:center;flex-wrap:wrap}#world-chart-view progress{flex:1;min-width:100px;height:5px;accent-color:#addbe0}#world-chart-view #world-chart-result{margin-top:10px;color:#add6c8}
      #world-chart-view #world-chart-account{font-size:13px;color:#afc6d0;margin-top:5px}#world-chart-view .rain-score{font-size:12px;color:#a5c0ca}#world-chart-view #world-chart-media-error{color:#ffd0a0;font-size:13px}
      @media(max-width:800px){#world-chart-view{font-size:13px}#world-chart-view header{padding:16px;gap:10px}#world-chart-view h1{font-size:20px}#world-chart-view .rain-chart-stage{padding:12px 16px}#world-chart-view footer{padding:12px 16px}#world-chart-view .rain-playing-caption{left:29px;top:21px}}

